// Member finance overview and the branch cashier's receipt workspace.
// All posted balances come from authorized database operations; preview amounts are estimates only.
function financeToday(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),value=type=>parts.find(p=>p.type===type).value;return `${value('year')}-${value('month')}-${value('day')}`;}
function financeClock(){return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());}
function financeTime(value){if(!value)return 'Time not recorded';const parts=value.split(':');const hour=Number(parts[0]);return `${hour%12||12}:${parts[1]} ${hour>=12?'PM':'AM'}`;}
function financeRecordedTime(value){return value?new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Not recorded';}
function financeDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return 'Date not recorded';const date=new Date(value+'T12:00:00Z');return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('en-PH',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'}).format(date):'Date not recorded';}
function installmentPaid(row){const amount=Number(row.amount)||0;return row.status==='Paid'?amount:Math.max(0,Math.min(amount,Number(row.paid_amount)||0));}
function installmentRemaining(row){return Math.max(0,Math.round(((Number(row.amount)||0)-installmentPaid(row))*100)/100);}
function unpaidInstallments(financial){return (financial?.schedule||[]).map((row,index)=>({...row,index,remaining:installmentRemaining(row)})).filter(row=>!['Paid','Cancelled'].includes(row.status)&&row.remaining>0&&/^\d{4}-\d{2}-\d{2}$/.test(row.date)).sort((a,b)=>a.date.localeCompare(b.date)||a.index-b.index);}
function nextMemberPayment(financial){return financial?unpaidInstallments(financial)[0]||null:null;}
function shareCapitalValue(financial){return financial?.share_capital===null||financial?.share_capital===undefined?'Not yet verified':money(financial.share_capital);}
function financeSummaryTile(label,value,hint,iconName,kind=''){return `<section class="member-finance-tile ${kind}"><div class="member-finance-label">${icon(iconName)}<span>${e(label)}</span></div><strong>${value}</strong><small>${e(hint)}</small></section>`;}
function memberFinancialDashboard(financial){const next=nextMemberPayment(financial),day=financeToday(),pending='Awaiting verified records';return `<section class="member-finance-dashboard" aria-label="My financial overview">${financeSummaryTile('Savings',financial?money(financial.savings):pending,financial?'Available savings balance':'Awaiting branch verification','wallet','savings-tile')}${financeSummaryTile('Share capital',financial?e(shareCapitalValue(financial)):pending,financial?.share_capital===null||financial?.share_capital===undefined?'Your branch will verify this balance':'Your paid-up cooperative capital','users')}${financeSummaryTile('Outstanding loans',financial?money(financial.loan_balance):pending,financial?(Number(financial.loan_balance)===0&&next?'Principal paid · Schedule review required':financial.loan_status):'Awaiting branch verification','card')}${financeSummaryTile('Next payment due',next?money(next.remaining):financial?Number(financial.loan_balance)>0?'Schedule not recorded':'No payment due':pending,next?financeDate(next.date)+(next.date<day?' · Overdue':next.date===day?' · Due today':''):financial&&Number(financial.loan_balance)>0?'Contact your branch for the schedule':'Only verified records appear here','calendar',next&&next.date<day?'payment-overdue':'')}</section>`;}
function memberFinanceDetails(financial){const id=S.me.id;return `<section class="card member-finance-details"><div class="member-finance-meta"><span>${financial?'Balances updated as of '+e(financeDate(financial.as_of)):'Your balances appear after branch verification.'}</span><button type="button" class="outline small" onclick="reload()">${icon('switch')} Refresh</button></div><details class="finance-disclosure"><summary>${icon('calendar')}<span>Payment schedule</span><small>${financial?.schedule?.length||0} installments</small></summary>${financial?scheduleView(financial.schedule):empty('No schedule yet','Only approved document records appear here.')}</details><details class="finance-disclosure"><summary>${icon('file')}<span>Payment history</span><small>${S.payments.filter(p=>p.member_id===id).length} receipts</small></summary><div id="memberPaymentHistory">${paymentHistoryList(id,'member', 'memberPaymentHistory')}</div></details>${S.page==='Accounts'&&financial?`<dl class="details-list member-loan-details">${detail('Loan status',e(financial.loan_status))}${detail('Annual interest',e(financial.annual_interest)+'%')}${detail('Record reference',e(financial.source_reference))}</dl>`:''}</section>`;}
async function loadCashierPayments(){S.payments=[];S.paymentsReady=false;S.paymentsError='';try{S.payments=await allRows('/rest/v1/occci_cashier_payments?select=*&order=payment_date.desc,created_at.desc,id');S.paymentsReady=true;}catch(err){S.paymentsError=err.message.includes('Workflow database setup is pending')?'Cashier payments need database activation. Existing verified balances remain available.':err.message;}}
function canReadPayment(payment){const member=S.profiles.find(p=>p.id===payment.member_id);return payment.member_id===S.session?.user?.id||Boolean(member&&canReadProfile(member)&&canReadBranch(payment.branch_id));}
function paymentHistoryList(id,context,rootId){if(!S.paymentsReady)return `<p class="hint">${e(S.paymentsError||'Payment receipts will appear once cashier records are available.')}</p>`;const rows=S.payments.filter(p=>p.member_id===id&&canReadPayment(p)),key=context+':'+id,size=20,pages=Math.max(1,Math.ceil(rows.length/size));S.paymentPages[key]=Math.min(pages,Math.max(1,S.paymentPages[key]||1));const page=S.paymentPages[key],start=(page-1)*size;return `${rows.length?`<ul class="payment-receipt-list">${rows.slice(start,start+size).map(p=>`<li><details><summary><span><strong>${e(p.receipt_number)}</strong><small>${e(financeDate(p.payment_date))}${p.payment_time?' · '+e(financeTime(p.payment_time))+' PHT':''}</small></span><b>${money(p.total_amount)}</b>${icon('down')}</summary><div class="payment-receipt-body"><dl class="finance-record-values">${detail('Payment time (PHT)',e(financeTime(p.payment_time)))}${detail('Recorded at (PHT)',e(financeRecordedTime(p.created_at)))}${detail('Principal paid',money(p.principal_amount))}${detail('Interest paid',money(p.interest_amount))}${detail('Fees paid',money(p.fees_amount))}${detail('Savings deposit',money(p.savings_amount))}${detail('Share capital contribution',money(p.share_capital_amount))}${detail('Loan balance after',money(p.loan_balance_after))}</dl><p>${e(p.cashier_name)} · Branch Cashier (BC)</p><p class="hint">${e(p.note)}</p></div></details></li>`).join('')}</ul>`:'<p class="hint">No cashier receipts recorded yet.</p>'}${rows.length?`<nav class="pagination payment-history-pager" aria-label="Payment history pages"><span>${start+1}–${Math.min(start+size,rows.length)} of ${rows.length} receipts</span><div class="flex"><button type="button" class="outline small" onclick="changePaymentHistoryPage('${id}','${context}','${rootId}',${page-1})" ${page===1?'disabled':''}>Previous</button><span>Page ${page} of ${pages}</span><button type="button" class="outline small" onclick="changePaymentHistoryPage('${id}','${context}','${rootId}',${page+1})" ${page===pages?'disabled':''}>Next</button></div></nav>`:''}`;}
function changePaymentHistoryPage(id,context,rootId,page){S.paymentPages[context+':'+id]=page;const root=$(rootId);if(root)root.innerHTML=paymentHistoryList(id,context,rootId);}
function memberPaymentsDialog(id){const p=S.profiles.find(p=>p.id===id);if(!p||p.archived_at||!canReadProfile(p))return;openModal('Cashier receipts',`<p class="smalltext">${e(p.full_name)} · ${e(p.account_number||'ID not assigned')}</p><div id="dialogPaymentHistory">${paymentHistoryList(id,'dialog','dialogPaymentHistory')}</div>`);}
function cashierMembers(){if(S.role!=='BC')return [];const branch=S.assignment?.branch_id,q=S.cashierSearch.trim();return S.profiles.filter(p=>!p.archived_at&&p.branch_id===branch&&canReadProfile(p)&&p.registration_kind!=='Staff'&&!directoryAssignment(p)).filter(p=>!q||(S.cashierSearchBy==='id'?characterMatches(p.account_number,q):memberMatches(p,q))).sort(compareUserNames);}
function cashierMemberList(){const rows=cashierMembers(),size=20,pages=Math.max(1,Math.ceil(rows.length/size));S.cashierPage=Math.min(pages,Math.max(1,S.cashierPage));const start=(S.cashierPage-1)*size;return `<ul class="cashier-member-list">${rows.slice(start,start+size).map(p=>{const f=S.financials.find(f=>f.member_id===p.id);return `<li><button type="button" onclick="selectCashierMember('${p.id}')" aria-pressed="${S.cashierMemberId===p.id}"><span class="avatar">${avatarArt(p.avatar)}</span><span><strong>${e(p.full_name)}</strong><small>${e(p.account_number||'ID not assigned')}</small></span><b>${f?money(f.loan_balance):'Unverified'}</b></button></li>`;}).join('')}</ul>${rows.length?'':'<p class="hint">No matching members in your branch.</p>'}<nav class="pagination cashier-member-pager"><span>${rows.length} members · 20 per page</span><div class="flex"><button type="button" class="outline small" onclick="S.cashierPage--;refreshCashierMemberList()" ${S.cashierPage===1?'disabled':''}>Previous</button><span>${S.cashierPage} / ${pages}</span><button type="button" class="outline small" onclick="S.cashierPage++;refreshCashierMemberList()" ${S.cashierPage===pages?'disabled':''}>Next</button></div></nav>`;}
function refreshCashierMemberList(){const root=$('cashierMemberList');if(root)root.innerHTML=cashierMemberList();}
function selectCashierMember(id){if(!cashierMembers().some(p=>p.id===id))return;S.cashierMemberId=id;render();}
function clearCashierMember(){S.cashierMemberId='';render();}
function cashierView(){if(S.role!=='BC')return empty('Cashier workspace unavailable','The assigned Branch Cashier records payments for their own branch.');const p=S.profiles.find(p=>p.id===S.cashierMemberId&&!p.archived_at&&p.branch_id===S.assignment?.branch_id&&p.registration_kind!=='Staff'&&!directoryAssignment(p)),f=p?S.financials.find(f=>f.member_id===p.id):null;if(!p)S.cashierMemberId='';return heading('Branch cashier',e(bn(S.assignment?.branch_id))+' branch · Member payments and deposits')+`<div class="cashier-layout ${p?'has-selection':''}"><aside class="card cashier-search-panel"><h2>Select member</h2><div class="cashier-search-controls"><label>Find member<input type="search" value="${e(S.cashierSearch)}" placeholder="Name or account / ID number" oninput="S.cashierSearch=this.value;S.cashierPage=1;refreshCashierMemberList()"></label><label>Search by<select onchange="S.cashierSearchBy=this.value;S.cashierPage=1;refreshCashierMemberList()"><option value="any" ${S.cashierSearchBy==='any'?'selected':''}>Name or ID</option><option value="id" ${S.cashierSearchBy==='id'?'selected':''}>Account / ID</option></select></label></div><div id="cashierMemberList">${cashierMemberList()}</div></aside><section class="card cashier-record-panel">${p?`<header class="cashier-selected-member"><div><h2>${e(p.full_name)}</h2><p>${e(p.account_number||'ID not assigned')} · ${e(p.membership_status)}</p></div><button type="button" class="outline small cashier-change-member" onclick="clearCashierMember()">Change member</button></header>${memberFinancialDashboard(f)}${!S.paymentsReady?`<div class="cashier-notice"><h3>Cashier records need activation</h3><p>${e(S.paymentsError||'Activate the cashier database workflow, then refresh.')}</p>${button('Refresh','reload()','outline','switch')}</div>`:!f||p.membership_status!=='Active'||!p.account_number?`<div class="cashier-notice"><h3>Verified records required</h3><p>Membership, an official ID and DM-verified balances are required before recording a receipt.</p>${p.membership_status==='Active'&&p.account_number?button('Submit actual records',`syncDialog('${p.id}')`,'outline','file'):button('View member',`memberDialog('${p.id}')`,'outline','user')}</div>`:cashierPaymentForm(p,f)}<details class="finance-disclosure cashier-schedule" open><summary>${icon('calendar')}<span>Payment schedule</span><small>${f?.schedule?.length||0} installments</small></summary>${f?scheduleView(f.schedule):'<p class="hint">No verified payment schedule yet.</p>'}</details><details class="finance-disclosure"><summary>${icon('file')}<span>Receipt history</span></summary><div id="cashierPaymentHistory">${paymentHistoryList(p.id,'cashier','cashierPaymentHistory')}</div></details>`:empty('Choose a member','Search by name or account / ID number to view balances and record a payment.')}</section></div>`;}
function cashierAmountField(label,name,{max='',disabled=false,hint=''}={}){return `<label>${e(label)}<input name="${name}" type="number" min="0" ${max!==''?`max="${e(max)}"`:''} step="0.01" value="0.00" inputmode="decimal" ${disabled?'disabled':''}>${hint?`<small>${e(hint)}</small>`:''}</label>`;}
function cashierPaymentForm(p,f){const rows=unpaidInstallments(f),next=nextMemberPayment(f),unknownCapital=f.share_capital===null||f.share_capital===undefined;return `<form id="cashierPaymentForm" class="cashier-payment-form" oninput="cashierPaymentPreview(this)" onchange="cashierPaymentPreview(this)" onsubmit="event.preventDefault();recordCashierPayment(this,'${p.id}')"><h3>Record receipt</h3><div class="cashier-form-grid"><label>Official receipt number<input name="receipt_number" maxlength="80" minlength="3" placeholder="Receipt / OR number" autocomplete="off" required></label><label>Payment date<input name="payment_date" type="date" min="1900-01-01" max="${financeToday()}" value="${financeToday()}" required></label><label>Payment time (PHT)<input name="payment_time" type="time" value="${financeClock()}" required></label><label class="full">Apply principal and interest to<select name="schedule_index"><option value="">Unallocated / extra principal</option>${rows.map(row=>`<option value="${row.index}" ${next?.index===row.index?'selected':''}>${e(financeDate(row.date))} · ${money(row.remaining)} remaining${row.date<financeToday()?' · Overdue':''}</option>`).join('')}</select><small>Principal and interest count toward the selected installment. Fees and deposits are separate.</small></label>${cashierAmountField('Principal paid','principal_amount',{max:f.loan_balance,hint:'Reduces the loan balance'})}${cashierAmountField('Interest paid','interest_amount')}${cashierAmountField('Fees paid','fees_amount')}${cashierAmountField('Savings deposit','savings_amount')}${cashierAmountField('Share capital contribution','share_capital_amount',{disabled:unknownCapital,hint:unknownCapital?'Opening balance needs BM / DM verification':'Use the amount on the receipt'})}<label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required></textarea></label><label class="full">Secret cashier PIN<input name="cashier_pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="off" required><small>Six digits. Create or replace your PIN in Settings.</small></label></div><div id="cashierPaymentPreview" class="cashier-payment-preview" aria-live="polite">${cashierPreviewValues(f,{principal_amount:0,interest_amount:0,fees_amount:0,savings_amount:0,share_capital_amount:0})}</div><p id="cashierPaymentError" role="alert" class="form-error" hidden></p><div class="cashier-payment-actions"><button type="submit" class="primary">${icon('check')} Record payment</button><button type="button" class="outline" onclick="reload()">Refresh balance</button></div><p class="hint">Enter the actual receipt breakdown. No automatic interest or share capital percentage is applied. Posted receipts are permanent; corrections use the BM / DM document review workflow.</p></form>`;}
function cashierMoney(value){const text=String(value??'').trim()||'0';if(!/^\d{1,14}(\.\d{1,2})?$/.test(text)||!Number.isSafeInteger(Math.round(Number(text)*100)))throw Error('Enter nonnegative amounts with at most two decimal places.');return Number(text);}
function cashierAmounts(form){return Object.fromEntries(['principal_amount','interest_amount','fees_amount','savings_amount','share_capital_amount'].map(key=>[key,cashierMoney(form.elements[key]?.disabled?'0':form.elements[key]?.value)]));}
function cashierPreviewValues(f,values){const total=Object.values(values).reduce((sum,value)=>sum+Math.round(value*100),0)/100,balance=Math.round((Number(f.loan_balance)-values.principal_amount)*100)/100,capital=f.share_capital===null||f.share_capital===undefined?null:Number(f.share_capital)+values.share_capital_amount;return `<dl><div><dt>Total received</dt><dd>${money(total)}</dd></div><div><dt>Loan balance after payment</dt><dd class="${balance<0?'form-error':''}">${money(balance)}</dd></div><div><dt>Savings after deposit</dt><dd>${money(Number(f.savings)+values.savings_amount)}</dd></div><div><dt>Share capital after contribution</dt><dd>${capital===null?'Not yet verified':money(capital)}</dd></div></dl>`;}
function cashierPaymentPreview(form){const f=S.financials.find(f=>f.member_id===S.cashierMemberId),error=form.querySelector('#cashierPaymentError');if(!f)return;try{const values=cashierAmounts(form);form.querySelector('#cashierPaymentPreview').innerHTML=cashierPreviewValues(f,values);if(values.principal_amount>Number(f.loan_balance))throw Error('Principal paid cannot exceed the outstanding loan balance.');const index=form.elements.schedule_index.value;if(index!==''){const row=f.schedule[Number(index)];if(!row||Math.round((values.principal_amount+values.interest_amount)*100)>Math.round(installmentRemaining(row)*100))throw Error('The principal and interest exceed the remaining installment. Choose an unallocated payment for extra principal.');}error.hidden=true;error.textContent='';}catch(err){error.textContent=err.message;error.hidden=false;}}
async function recordCashierPayment(form,id){if(form.dataset.saving==='true')return;const button=form.querySelector('button[type=submit]'),error=form.querySelector('#cashierPaymentError');form.dataset.saving='true';button.disabled=true;error.hidden=true;let posted=false;try{const p=S.profiles.find(p=>p.id===id),f=S.financials.find(f=>f.member_id===id);if(S.role!=='BC'||!S.paymentsReady||!p||p.archived_at||p.branch_id!==S.assignment?.branch_id||p.registration_kind==='Staff'||directoryAssignment(p)||p.membership_status!=='Active'||!p.account_number||!f)throw Error('Choose a verified member in your assigned branch.');const values=cashierAmounts(form),receipt=form.elements.receipt_number.value.trim(),paidOn=form.elements.payment_date.value,reason=form.elements.reason.value.trim(),scheduleIndex=form.elements.schedule_index.value;if(!/^[A-Za-z0-9][A-Za-z0-9 /._#-]{2,79}$/.test(receipt)||reason.length<3)throw Error('Enter the official receipt number and notes.');scheduleDate(paidOn);if(paidOn>financeToday()||paidOn<'1900-01-01')throw Error('Choose a payment date that is not in the future.');if(Object.values(values).reduce((sum,value)=>sum+value,0)<=0)throw Error('Enter a positive payment or deposit amount.');if(values.principal_amount>Number(f.loan_balance))throw Error('Principal paid cannot exceed the outstanding loan balance.');if(values.share_capital_amount>0&&(f.share_capital===null||f.share_capital===undefined))throw Error('Verify the opening share capital balance through BM and DM first.');if(scheduleIndex!==''){const row=f.schedule[Number(scheduleIndex)];if(!row||['Paid','Cancelled'].includes(row.status)||values.principal_amount+values.interest_amount<=0||Math.round((values.principal_amount+values.interest_amount)*100)>Math.round(installmentRemaining(row)*100))throw Error('Choose an unpaid installment with enough remaining amount, or use an unallocated payment.');}const pin=form.elements.cashier_pin?.value||'',paymentTime=form.elements.payment_time?.value||'';if(!/^[0-9]{6}$/.test(pin))throw Error('Enter your six-digit cashier PIN.');if(!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(paymentTime))throw Error('Choose a valid payment time.');const pinStatus=await rpc('occci_cashier_pin_status',{});if(!pinStatus?.configured)throw Error('Create your secret PIN in Settings before recording a payment.');form.dataset.paymentId||=crypto.randomUUID();const result=await rpc('occci_record_cashier_payment',{target:id,values_json:{...values,receipt_number:receipt,payment_date:paidOn,payment_time:paymentTime,cashier_pin:pin,schedule_index:scheduleIndex===''?null:Number(scheduleIndex)},expected_revision:f.revision,client_reference:form.dataset.paymentId,reason});if(result?.error)throw Error(result.error);posted=true;await (typeof refreshAfterWrite==='function'?refreshAfterWrite({resetForms:true}):reload());toast(S.error?'Receipt recorded. Refresh to load the current balances.':'Receipt '+result.receipt_number+' recorded. Member balances and schedule updated.');}catch(err){error.textContent=err.message;error.hidden=false;}finally{if(form.elements.cashier_pin)form.elements.cashier_pin.value='';form.dataset.saving='false';button.disabled=posted;}}

function cashierSettingsView(){return heading('Cashier settings','Secure payment recording')+`<section class="card"><h2>Secret payment PIN</h2><p class="smalltext">Use a six-digit PIN to confirm each receipt. Creating or replacing it requires your own account password.</p>${button('Create / replace PIN','cashierPinDialog()','primary','shield')}</section><section class="card"><h2>Account password</h2><p class="smalltext">Explain your request first. Your assigned BM must approve before you change or recover your password.</p><div class="flex">${button('Change password',"cashierPasswordRequestDialog('Change password')",'outline','shield')}${button('Recover password',"cashierPasswordRequestDialog('Recover password')",'outline','shield')}${button('My requests',"go('Password requests')",'outline','clock')}</div></section>`;}
function cashierPinDialog(){if(S.role!=='BC')return;openModal('Create / replace cashier PIN',`<form onsubmit="event.preventDefault();saveCashierPin(this)"><div class="form-grid"><label>New six-digit PIN<input name="new_pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" required></label><label>Confirm PIN<input name="confirm_pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" required></label><label class="full">Confirm your account password<input name="account_password" type="password" autocomplete="current-password" maxlength="1024" required></label></div><p class="hint">Enter the password for your signed-in cashier account. Replacing a forgotten PIN requires this password too.</p><button type="submit" class="primary">Save PIN</button></form>`);}
async function saveCashierPin(form){const btn=form.querySelector('[type=submit]');if(form.dataset.saving==='true')return;form.dataset.saving='true';btn.disabled=true;let fresh=null;try{if(S.role!=='BC')throw Error('Only Branch Cashier can set a payment PIN.');const f=new FormData(form),pin=String(f.get('new_pin')||''),password=String(f.get('account_password')||''),id=S.session?.user?.id,email=S.session?.user?.email;if(!/^[0-9]{6}$/.test(pin)||pin!==f.get('confirm_pin'))throw Error('Enter matching six-digit PINs.');if(!password||!email)throw Error('Confirm your own account password.');const confirmation=await rpc('occci_begin_cashier_pin',{new_pin:pin});try{fresh=await api('/auth/v1/token?grant_type=password',{method:'POST',auth:false,data:{email,password}});}catch{throw Error('Password confirmation failed. Check your account password.');}if(fresh.user?.id!==id||!fresh.access_token||S.session?.user?.id!==id)throw Error('Confirm the password of the signed-in cashier.');await api('/rest/v1/rpc/occci_set_cashier_pin',{method:'POST',auth:false,headers:{Authorization:'Bearer '+fresh.access_token},data:{confirmation}});closeModal();toast('Secret PIN saved. Use it to confirm each payment.');}catch(err){$('actionMessage').textContent=err.message;}finally{for(const name of ['new_pin','confirm_pin','account_password'])if(form.elements[name])form.elements[name].value='';form.dataset.saving='false';btn.disabled=false;if(fresh?.access_token)try{await api('/auth/v1/logout?scope=local',{method:'POST',auth:false,headers:{Authorization:'Bearer '+fresh.access_token}});}catch{}}}
